@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RecordVisitScreen(
  patientName: String,
  loadQuestionnaireJson: suspend () -> String,
  onSaved: (QuestionnaireResponse) -> Unit,
  onCancel: () -> Unit,
) {
  var questionnaireJson by remember { mutableStateOf<String?>(null) }
  val scope = rememberCoroutineScope()

  LaunchedEffect(Unit) { questionnaireJson = loadQuestionnaireJson() }

  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text("New visit — $patientName") },
        navigationIcon = { TextButton(onClick = onCancel) { Text("Cancel") } },
      )
    }
  ) { padding ->
    val json = questionnaireJson
    Box(Modifier.fillMaxSize().padding(padding)) {
      if (json == null) {
        CircularProgressIndicator(androidx.compose.ui.Modifier.align(Alignment.Center))
      } else {
        Questionnaire(
          questionnaireJson = json,
          onSubmit = { getResponse ->
            scope.launch {
              try {
                val response = getResponse()
                onSaved(response)
              } catch (e: CancellationException) {
                // Answer validation failed; the form already shows per-question errors.
              }
            }
          },
          onCancel = onCancel,
        )
      }
    }
  }
}

