  var visitsLoading by remember { mutableStateOf(true) }
  var visitsRefreshKey by remember { mutableIntStateOf(0) }

  val scope = rememberCoroutineScope()
  val appCtx = androidx.compose.ui.platform.LocalContext.current.applicationContext

  LaunchedEffect(Unit) {
    kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
      try {
        val url = java.net.URL("http://10.0.2.2:8080/fhir/Patient?_count=1")
        val conn = url.openConnection() as java.net.HttpURLConnection
        conn.connectTimeout = 5000
        conn.readTimeout = 5000
        android.util.Log.e("AncDiag", "raw connect code=${conn.responseCode}")
      } catch (e: Exception) {
        android.util.Log.e("AncDiag", "raw connect failed", e)
      }
      try {
        val ctx = appCtx
        val diagWorker =
          object : dev.ohs.fhir.engine.sync.FhirSyncTask {
            override fun getFhirEngine() = dev.ohs.fhir.engine.FhirEngineProvider.getInstance(ctx)

            override fun getDownloadWorkManager(): dev.ohs.fhir.engine.sync.DownloadWorkManager =
              dev.ohs.fhir.engine.sync.download.ResourceParamsBasedDownloadWorkManager(
                syncParams =
                  mapOf(
                    dev.ohs.fhir.model.r4.terminologies.ResourceType.Patient to emptyMap()
                  ),
